using i128 = __int128_t;
using ll = long long;

i128 floor_div(i128 a, i128 b) {
    i128 q = a / b;
    i128 r = a % b;
    if (r < 0) --q;
    return q;
}

i128 ceil_div(i128 a, i128 b) {
    i128 q = a / b;
    i128 r = a % b;
    if (r > 0) ++q;
    return q;
}

i128 ext_gcd(i128 a, i128 b, i128 &x, i128 &y) {
    i128 old_r = a, r = b;
    i128 old_x = 1, cur_x = 0;
    i128 old_y = 0, cur_y = 1;

    while (r != 0) {
        i128 q = old_r / r;

        i128 nr = old_r - q * r;
        old_r = r;
        r = nr;

        i128 nx = old_x - q * cur_x;
        old_x = cur_x;
        cur_x = nx;

        i128 ny = old_y - q * cur_y;
        old_y = cur_y;
        cur_y = ny;
    }

    x = old_x;
    y = old_y;
    return old_r;
}

