#include <bits/stdc++.h>
using namespace std;

using ll = long long;
using i128 = __int128_t;

i128 gcd128(i128 a, i128 b) {
    while (b != 0) {
        i128 t = a % b;
        a = b;
        b = t;
    }
    return a;
}

i128 extendedGcd(i128 a, i128 b, i128& x, i128& y) {
    if (b == 0) {
        x = 1;
        y = 0;
        return a;
    }
    i128 x1, y1;
    i128 g = extendedGcd(b, a % b, x1, y1);
    x = y1;
    y = x1 - (a / b) * y1;
    return g;
}

i128 mod(i128 value, i128 modulus) {
    value %= modulus;
    if (value < 0) value += modulus;
    return value;
}

i128 floorDiv(i128 value, i128 divisor) {
    i128 result = value / divisor;
    if (value % divisor < 0) --result;
    return result;
}

i128 ceilDiv(i128 value, i128 divisor) {
    i128 result = value / divisor;
    if (value % divisor > 0) ++result;
    return result;
}

void printInt128(i128 value) {
    if (value == 0) {
        putchar('0');
        putchar('\n');
        return;
    }
    if (value < 0) {
        putchar('-');
        value = -value;
    }
    string result;
    while (value > 0) {
        result.push_back(char('0' + value % 10));
        value /= 10;
    }
    reverse(result.begin(), result.end());
    puts(result.c_str());
}

