    ll aInput, k1Input, bInput, k2Input, lInput, rInput;
    if (scanf("%lld%lld%lld%lld%lld%lld",
              &aInput, &k1Input, &bInput, &k2Input, &lInput, &rInput) != 6) {
        return 0;
    }

    i128 a = aInput, b = bInput;
    i128 k1 = k1Input, k2 = k2Input;
    i128 l = lInput, r = rInput;

    if (a <= 0 || b <= 0) {
        puts("0");
        return 0;
    }

    i128 lower = max(l, max(k1, k2));
    if (lower > r) {
        puts("0");
        return 0;
    }

    i128 g = gcd128(a, b);
    i128 difference = k2 - k1;

    if (difference % g != 0) {
        puts("0");
        return 0;
    }

    i128 reducedA = a / g;
    i128 reducedB = b / g;
    i128 xResidue = 0;

    if (reducedB != 1) {
        i128 inverse, unused;
        extendedGcd(reducedA, reducedB, inverse, unused);
        xResidue = mod(mod(difference / g, reducedB) *
                       mod(inverse, reducedB), reducedB);
